import React from 'react';

export function ProgressBar({ value }: { value: number }) {
  const clamped = Math.max(0, Math.min(100, value));
  return (
    <div role="progressbar" aria-valuenow={clamped} aria-valuemin={0} aria-valuemax={100}
      style={{ width: '100%', height: '8px', borderRadius: '999px', background: '{{token:colors.glass.tint}}', overflow: 'hidden' }}>
      <div style={{ width: `${clamped}%`, height: '100%', borderRadius: '999px', background: '{{token:colors.accent.primary}}', transition: '{{token:animation.transition.default}}' }} />
    </div>
  );
}
